import{_ as i,c as l,o as s,ae as t}from"./chunks/framework.DMK_uHmU.js";const h=JSON.parse('{"title":"User Profile Privileges Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-privileges.md","filePath":"Administration/Manage/Users/user-privileges.md"}'),n={name:"Administration/Manage/Users/user-privileges.md"};function a(o,e,r,c,u,d){return s(),l("div",null,e[0]||(e[0]=[t('<h1 id="user-profile-privileges-guide" tabindex="-1">User Profile Privileges Guide <a class="header-anchor" href="#user-profile-privileges-guide" aria-label="Permalink to &quot;User Profile Privileges Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Profile Privileges component allows administrators to manage access controls and feature permissions for individual users. These settings determine which parts of the application a user can access and what capabilities they have within the system.</p><h2 id="accessing-user-privileges" tabindex="-1">Accessing User Privileges <a class="header-anchor" href="#accessing-user-privileges" aria-label="Permalink to &quot;Accessing User Privileges&quot;">​</a></h2><p>The User Privileges component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to a user profile page (<code>/user/profile/[user_id]</code>)</li><li>Click on the &quot;Privileges&quot; tab in the left navigation menu</li></ol><h2 id="user-privileges-interface-overview" tabindex="-1">User Privileges Interface Overview <a class="header-anchor" href="#user-privileges-interface-overview" aria-label="Permalink to &quot;User Privileges Interface Overview&quot;">​</a></h2><p>The User Privileges interface is organized into three main sections:</p><ol><li><strong>Admin Access Levels</strong> (visible only when user&#39;s role is set to &quot;Admin&quot;)</li><li><strong>User Application Modules</strong></li><li><strong>Assistant Features</strong></li></ol><p>Each section contains multiple toggle switches and button groups that control specific permissions.</p><h2 id="admin-access-privileges" tabindex="-1">Admin Access Privileges <a class="header-anchor" href="#admin-access-privileges" aria-label="Permalink to &quot;Admin Access Privileges&quot;">​</a></h2><p>This section appears only when a user&#39;s access level is set to &quot;Admin&quot; and allows fine-grained control over administrative functions.</p><p>For each administrative area, you can set one of three permission levels:</p><ul><li><strong>No Access</strong>: User cannot view or modify this area</li><li><strong>Read Only</strong>: User can view but not modify content in this area</li><li><strong>Full Access</strong>: User can view and modify all content in this area</li></ul><p>The administrative areas include:</p><ol><li><p><strong>User Management</strong></p><ul><li>Controls access to user creation, editing, and deletion</li><li>When set to &quot;Read Only&quot;, users can view other user accounts but not modify them</li><li>When set to &quot;Full Access&quot;, users can create, edit, and delete user accounts</li></ul></li><li><p><strong>Group Management</strong></p><ul><li>Controls access to organizational group configuration</li><li>Read Only allows viewing groups but not modifying membership</li><li>Full Access allows creating, editing, and deleting groups</li></ul></li><li><p><strong>Settings - AI / Global</strong></p><ul><li>Controls access to system-wide settings</li><li>Read Only allows viewing settings but not changing them</li><li>Full Access allows modifying any system setting</li></ul></li><li><p><strong>Content Manager</strong></p><ul><li>Controls access to content administration tools</li><li>Read Only allows viewing content without modification rights</li><li>Full Access allows creating, editing, and deleting content</li></ul></li><li><p><strong>Blueprint Management</strong></p><ul><li>Controls access to AI conversation templates</li><li>Read Only allows viewing blueprints but not modifying them</li><li>Full Access allows creating and modifying blueprints</li></ul></li><li><p><strong>Knowledge Bases Management</strong></p><ul><li>Controls access to knowledge base configuration</li><li>Read Only allows viewing knowledge bases but not modifying them</li><li>Full Access allows creating and modifying knowledge bases</li></ul></li><li><p><strong>Dashboard Insights</strong></p><ul><li>Controls access to analytics and reporting</li><li>Read Only allows viewing dashboards</li><li>Full Access allows configuring and exporting from dashboards</li></ul></li><li><p><strong>Test Management</strong></p><ul><li>Controls access to AI test case creation and evaluation</li><li>Read Only allows viewing test cases and results</li><li>Full Access allows creating and running tests</li></ul></li></ol><h2 id="user-application-modules" tabindex="-1">User Application Modules <a class="header-anchor" href="#user-application-modules" aria-label="Permalink to &quot;User Application Modules&quot;">​</a></h2><p>This section controls which application modules are available to the user in the main navigation menu.</p><p>Each toggle enables or disables a specific module:</p><ol><li><p><strong>Content View</strong></p><ul><li>When enabled: User can access the content library view</li><li>When disabled: Content library option will not appear in the menu</li></ul></li><li><p><strong>Search View</strong></p><ul><li>When enabled: User can access the advanced search interface</li><li>When disabled: Search view will not be available</li></ul></li><li><p><strong>Learn Platform</strong></p><ul><li>When enabled: User can access learning materials and modules</li><li>When disabled: Learning platform will not be available</li></ul></li></ol><p>Disabling all modules will result in the user only seeing the Assistant when they log in.</p><h2 id="assistant-features" tabindex="-1">Assistant Features <a class="header-anchor" href="#assistant-features" aria-label="Permalink to &quot;Assistant Features&quot;">​</a></h2><p>This section controls specific features within the AI Assistant interface.</p><p>Each toggle enables or disables a specific feature:</p><ol><li><p><strong>Assistant Chat Bot</strong></p><ul><li>When enabled: User can interact with the chatbot assistant</li><li>When disabled: Chat functionality is not available</li><li>Default: Enabled</li></ul></li><li><p><strong>LaunchPad</strong></p><ul><li>When enabled: User can access the LaunchPad home screen</li><li>When disabled: User will not see the LaunchPad interface</li><li>Default: Enabled</li></ul></li><li><p><strong>Assistant Control Panel</strong></p><ul><li>When enabled: User can access the control panel to manage chat sessions</li><li>When disabled: Control panel will not be available</li><li>Default: Enabled</li></ul></li><li><p><strong>Assistant Content Selector</strong></p><ul><li>When enabled: User can select specific content to include in chat sessions</li><li>When disabled: Content selection will not be available</li><li>Default: Enabled</li></ul></li><li><p><strong>Assistant AI Settings</strong></p><ul><li>When enabled: User can modify AI behavior settings</li><li>When disabled: AI settings cannot be modified by the user</li><li>Default: Enabled</li></ul></li><li><p><strong>Assistant Blueprints</strong></p><ul><li>When enabled: User can access and use conversation blueprints</li><li>When disabled: Blueprint functionality is not available</li><li>Default: Enabled</li></ul></li><li><p><strong>Assistant Chat History</strong></p><ul><li>When enabled: User can view and access their previous chat sessions</li><li>When disabled: Chat history will not be stored or accessible</li><li>Default: Enabled</li></ul></li><li><p><strong>Keep Chat History Duration</strong></p><ul><li>Numeric value in days</li><li>Controls how long chat history is retained before automatic deletion</li><li>Enter 0 for no automatic deletion (permanent retention)</li><li>Default: 30 days</li></ul></li></ol><h2 id="privilege-settings-and-their-impact" tabindex="-1">Privilege Settings and Their Impact <a class="header-anchor" href="#privilege-settings-and-their-impact" aria-label="Permalink to &quot;Privilege Settings and Their Impact&quot;">​</a></h2><h3 id="effects-of-disabling-key-features" tabindex="-1">Effects of Disabling Key Features <a class="header-anchor" href="#effects-of-disabling-key-features" aria-label="Permalink to &quot;Effects of Disabling Key Features&quot;">​</a></h3><ol><li><p><strong>Disabled Control Panel</strong>:</p><ul><li>User cannot manage chat sessions</li><li>User cannot select content to include in chats</li><li>User cannot adjust AI settings</li></ul></li><li><p><strong>Disabled LaunchPad</strong>:</p><ul><li>User will not see the customized content homepage</li><li>User must navigate directly to features</li></ul></li><li><p><strong>Disabled Chat History</strong>:</p><ul><li>Previous conversations will not be accessible</li><li>Each session starts fresh with no context from previous interactions</li></ul></li></ol><h3 id="admin-access-level-combinations" tabindex="-1">Admin Access Level Combinations <a class="header-anchor" href="#admin-access-level-combinations" aria-label="Permalink to &quot;Admin Access Level Combinations&quot;">​</a></h3><p>For users with Admin access, the privilege combinations determine what they can do in the administration sections:</p><ol><li><strong>Content Management Example</strong>: <ul><li>No Access: Admin cannot see the Content section</li><li>Read Only: Admin can view content but not create/edit/delete</li><li>Full Access: Admin can perform all content operations</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Principle of Least Privilege</strong>:</p><ul><li>Grant only the permissions necessary for the user&#39;s role</li><li>Start with minimal privileges and add as needed</li></ul></li><li><p><strong>Role-Based Configuration</strong>:</p><ul><li>Create consistent privilege sets based on job functions</li><li>Maintain similar settings for users with similar roles</li></ul></li><li><p><strong>Chat History Retention</strong>:</p><ul><li>Set appropriate retention periods based on: <ul><li>Organizational data policies</li><li>Compliance requirements</li><li>User productivity needs</li></ul></li></ul></li><li><p><strong>Regular Access Reviews</strong>:</p><ul><li>Periodically review privilege settings</li><li>Adjust access when user roles change</li></ul></li><li><p><strong>Admin Privileges</strong>:</p><ul><li>Reserve full admin access for a limited number of users</li><li>Use read-only access when possible for security</li></ul></li></ol><hr><p>For additional assistance with user privileges configuration, please contact your system administrator.</p>',37)]))}const p=i(n,[["render",a]]);export{h as __pageData,p as default};
